import {
  IconCircleCheck,
  IconMicrophone,
  IconShield,
  IconUsers,
} from "@tabler/icons-react";

type Tone = "light" | "blue" | "yellow" | "orange";

type FeatureCard = {
  id: "multilingual" | "quickExit" | "multiInput" | "guidedTriage";
  title: string;
  description: string;
  tone: Tone;
  Icon: typeof IconUsers;
};

const FEATURE_CARDS: FeatureCard[] = [
  {
    id: "multilingual",
    title: "Multilingual",
    description:
      "Native support for 12+ languages. We speak your language so you are heard clearly.",
    tone: "light",
    Icon: IconUsers,
  },
  {
    id: "quickExit",
    title: "Quick Exit",
    description:
      "Instant disguise mode with a single tap. Protect your privacy immediately when needed.",
    tone: "blue",
    Icon: IconShield,
  },
  {
    id: "multiInput",
    title: "Multi-Input",
    description:
      "Document incidents securely your way using voice, text, or images seamlessly.",
    tone: "yellow",
    Icon: IconMicrophone,
  },
  {
    id: "guidedTriage",
    title: "Guided Triage",
    description:
      "Direct path to professional support tailored to your specific situation and needs.",
    tone: "orange",
    Icon: IconCircleCheck,
  },
];

function toneClasses(tone: Tone) {
  if (tone === "blue") return "bg-[#0C5FA8] text-white";
  if (tone === "yellow") return "bg-[#ECE07D] text-[#1f2937]";
  if (tone === "orange") return "bg-[#FF9700] text-white";
  return "bg-[#f5f7fb] text-[#1f2937]";
}

export default function FeatureCardsSection() {
  return (
    <section className="relative z-20 -mt-10 bg-[#01579B] sm:-mt-12 lg:-mt-20 xl:-mt-[170px]">
      <div className="mx-auto w-full max-w-[1440px]">
        <div className="rounded-t-[64px] bg-[#FFFBF0] px-8 py-24 xl:h-[524.25px]">
          <div className="mx-auto grid w-full max-w-[1376px] grid-cols-1 gap-8 sm:grid-cols-2 xl:grid-cols-4">
            {FEATURE_CARDS.map(({ id, title, description, tone, Icon }) => (
              <article
                key={id}
                className={`relative min-h-[260px] overflow-hidden rounded-[24px] p-6 shadow-[0_10px_20px_rgba(15,23,42,0.1)] xl:h-[332.25px] ${toneClasses(tone)}`}
              >
                {tone === "light" && (
                  <span className="pointer-events-none absolute right-0 top-0 h-16 w-16 rounded-bl-[32px] bg-[#e4efeb]" />
                )}
                {tone === "blue" && (
                  <span className="pointer-events-none absolute -bottom-7 -left-7 h-16 w-16 rounded-full bg-[#084d88]" />
                )}
                {tone === "yellow" && (
                  <span className="pointer-events-none absolute -bottom-7 -right-7 h-20 w-20 rounded-full bg-[#f2c328]" />
                )}
                {tone === "orange" && (
                  <span className="pointer-events-none absolute bottom-7 left-6 h-[3px] w-24 rounded-full bg-white/90" />
                )}

                <Icon
                  className={`h-5 w-5 ${
                    tone === "light" || tone === "yellow"
                      ? "text-[#0f766e]"
                      : "text-white"
                  }`}
                  stroke={2}
                />

                <h3
                  className={`mt-4 text-[34px] font-semibold leading-[1.05] ${
                    tone === "light" || tone === "yellow"
                      ? "text-[#0f766e]"
                      : "text-white"
                  }`}
                >
                  {title}
                </h3>

                <p
                  className={`mt-3 text-sm leading-8 ${
                    tone === "light" || tone === "yellow"
                      ? "text-[#4b5563]"
                      : "text-white/90"
                  }`}
                >
                  {description}
                </p>

                {id === "multilingual" && (
                  <div className="mt-5 flex items-center gap-2 text-[10px] font-semibold text-[#0f766e]">
                    <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-[#d2f3e2]">
                      EN
                    </span>
                    <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-[#ffd6cf]">
                      ES
                    </span>
                    <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-[#ffe268]">
                      +
                    </span>
                  </div>
                )}

                {id === "quickExit" && (
                  <div className="mt-5 inline-flex rounded-full bg-[#084d88] px-3 py-1 text-[10px] font-semibold tracking-[0.08em] text-white">
                    COVERT MODE READY
                  </div>
                )}
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
